#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<long long> ans(n, 0);
    vector<int> st;
    long long prev = 0;  // first time point not yet assigned to any function
    for (int i = 0; i < m; i++) {
        string line;
        cin >> line;
        size_t p1 = line.find(':'), p2 = line.find(':', p1 + 1);
        int fid = stoi(line.substr(0, p1));
        string kind = line.substr(p1 + 1, p2 - p1 - 1);
        long long t = stoll(line.substr(p2 + 1));
        if (!st.empty()) ans[st.back()] += t - prev;  // [prev, t) belongs to the stack top
        if (kind == "start") {
            st.push_back(fid);
            prev = t;
        } else {
            ans[fid] += 1;  // the end timestamp itself is inclusive
            st.pop_back();
            prev = t + 1;
        }
    }
    for (int i = 0; i < n; i++) cout << ans[i] << (i + 1 < n ? ' ' : '\n');
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] ans = new long[n];
        int[] st = new int[Math.max(1, m)];
        int sp = 0;
        long prev = 0;  // first time point not yet assigned to any function
        for (int i = 0; i < m; i++) {
            String[] parts = next().split(":");
            int fid = Integer.parseInt(parts[0]);
            long t = Long.parseLong(parts[2]);
            if (sp > 0) ans[st[sp - 1]] += t - prev;  // [prev, t) belongs to the stack top
            if (parts[1].equals("start")) {
                st[sp++] = fid;
                prev = t;
            } else {
                ans[fid] += 1;  // the end timestamp itself is inclusive
                sp--;
                prev = t + 1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(ans[i]).append(i + 1 < n ? ' ' : '\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n, m := readInt(), readInt()
	ans := make([]int, n)
	st := []int{}
	prev := 0 // first time point not yet assigned to any function
	for i := 0; i < m; i++ {
		parts := strings.Split(readToken(), ":")
		fid, _ := strconv.Atoi(parts[0])
		t, _ := strconv.Atoi(parts[2])
		if len(st) > 0 {
			ans[st[len(st)-1]] += t - prev // [prev, t) belongs to the stack top
		}
		if parts[1] == "start" {
			st = append(st, fid)
			prev = t
		} else {
			ans[fid]++ // the end timestamp itself is inclusive
			st = st[:len(st)-1]
			prev = t + 1
		}
	}
	strs := make([]string, n)
	for i, v := range ans {
		strs[i] = strconv.Itoa(v)
	}
	fmt.Println(strings.Join(strs, " "))
}
